function validate([s, t]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (typeof t !== 'string' || t.length < 1 || t.length > 100000) return 't needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t may contain only lowercase letters.';
  return null;
}

