function appendCharacters(s, t) {
  // Try appending the last `count` characters of t, for count = 0, 1, 2, ...
  const isSubsequence = (small, big) => {
    let from = 0;
    for (const ch of small) {
      const at = big.indexOf(ch, from);
      if (at === -1) return false;
      from = at + 1;
    }
    return true;
  };
  for (let count = 0; count <= t.length; count++) {
    if (isSubsequence(t, s + t.slice(t.length - count))) return count;
  }
  return t.length;
}

