function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const word = length => Array.from({ length }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const sLength = size === 'large' ? 10000 : 1 + Math.floor(rand() * 8);
  const tLength = size === 'large' ? 1000 + Math.floor(rand() * 9001) : 1 + Math.floor(rand() * 6);
  const s = word(sLength);
  // Build t from a random subsequence of s followed by random letters, so answers vary.
  const keep = Math.floor(rand() * (tLength + 1));
  const picked = [];
  for (let i = 0; i < s.length && picked.length < keep; i++) if (rand() < keep / s.length + 0.05) picked.push(s[i]);
  const t = (picked.join('') + word(tLength)).slice(0, tLength);
  return [s, t];
}
